sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }



  var populateUser = new GlideAjax('x_938076_now_utils.getUserData');
  populateUser.addParam('sysparm_name', 'getUserData');
  populateUser.addParam('sysparm_userID', g_form.getValue('caller_id'));
  populateUser.getXMLAnswer(getResponse);

  function getResponse(answer){

	var parsedData = JSON.parse(answer);
	g_form.setValue('short_description' , 'Incident Raised by ' + parsedData.userNum + " " + "|" + parsedData.userEmail);
  }


 console.log('Test');

var getUserDetails = g_form.getReference('caller_id' , getDetails);

function getDetails(getUserDetails){
	g_form.setValue('description' , " The incident has been created  by " + getUserDetails.name + " " + "contact via " + getUserDetails.email);


}




}
